// Builds small, structurally valid Nintendo DS ROM images for the tests. The
// images contain only generated bytes: no code, logo or data from any game.
#pragma once

#include <cstdint>
#include <string>
#include <utility>
#include <vector>

#include "codecs.h"

namespace bd_test {

enum class OverlayStorage {
  Raw,
  Blz,         // Flagged as compressed in the overlay table.
  Lz40,        // Not flagged; this is how the real game stores its overlays.
  Lz40Twice,   // Not flagged, compressed two layers deep.
};

struct OverlaySpec {
  Bytes data;
  OverlayStorage storage = OverlayStorage::Raw;
  std::uint32_t ram_address = 0x02100000;
};

struct RomSpec {
  std::string title = "SYNTHETIC";
  std::string game_code = "BO5E";
  std::uint8_t rom_version = 0;
  bool compress_arm9 = true;
  bool decrypted_secure_area = true;
  bool with_module_params = true;
  bool swapped_markers = false;  // The start-up markers in the non-retail order.
  std::uint32_t sdk_version = 0x04020001;
  // Paths use '/' separators; file IDs are assigned after the overlays.
  std::vector<std::pair<std::string, Bytes>> files;
  std::vector<OverlaySpec> overlays;
};

struct BuiltRom {
  Bytes image;
  Bytes arm9_plain;  // The ARM9 program before compression.
  std::uint32_t fnt_offset = 0;
  std::uint32_t fnt_size = 0;
  std::uint32_t fat_offset = 0;
  std::uint32_t fat_size = 0;
  std::uint32_t overlay_table_offset = 0;
};

BuiltRom build_rom(const RomSpec& spec);

// A ROM with a nested directory tree, overlays and a compressed ARM9 program.
RomSpec default_spec();

// Recomputes the header checksum after a test has modified header bytes.
void fix_header_crc(Bytes& image);

void put_le16(Bytes& data, std::size_t offset, std::uint32_t value);
void put_le32(Bytes& data, std::size_t offset, std::uint32_t value);

}  // namespace bd_test
